def forward(self, images: torch.Tensor) -> torch.Tensor:
    if self.training:
        return self._forward_once(images)
    padded = F.pad(images, (1, 1, 1, 1), mode='replicate')
    views = (images, padded[:, :, 0:28, 1:29], padded[:, :, 2:30, 1:29], padded[:, :, 1:29, 0:28], padded[:, :, 1:29, 2:30])

    def collect_log_probabilities() -> list[torch.Tensor]:
        outputs = []
        for view in views:
            outputs.append(F.log_softmax(self._forward_once(view), dim=1))
            outputs.append(F.log_softmax(self._forward_once(view.flip(-1)), dim=1))
        return outputs
    log_probabilities = collect_log_probabilities()
    ema_state = getattr(self, '_ema_state', None)
    if ema_state is not None:
        live_state = dict(self.named_parameters())
        live_state.update(dict(self.named_buffers()))
        backups = {}
        with torch.no_grad():
            for name, average in ema_state.items():
                tensor = live_state[name]
                backups[name] = tensor.detach().clone()
                tensor.copy_(average)
        try:
            log_probabilities.extend(collect_log_probabilities())
        finally:
            with torch.no_grad():
                for name, backup in backups.items():
                    live_state[name].copy_(backup)
    return torch.logsumexp(torch.stack(log_probabilities, dim=0), dim=0) - math.log(len(log_probabilities))

