            log_probabilities.extend(collect_log_probabilities())
        finally:
            with torch.no_grad():
                for name, backup in backups.items():
                    live_state[name].copy_(backup)
    stacked_log_probabilities = torch.stack(log_probabilities, dim=0)
    if ema_state is None:
        ensemble_log_probabilities = torch.logsumexp(stacked_log_probabilities, dim=0) - math.log(len(log_probabilities))
    else:
        view_count = len(log_probabilities) // 2
        log_weights = stacked_log_probabilities.new_empty((len(log_probabilities), 1, 1))
