def forward(self, images: torch.Tensor) -> torch.Tensor:
    if self.training or self._ema_parameters is None:
        logits = self._forward_once(images)
        if not self.training:
            flipped_logits = self._forward_once(images.flip(-1))
            logits = 0.5 * (logits + flipped_logits)
        return logits
    parameters = list(self.parameters())
    live_parameters = [parameter.data for parameter in parameters]
    try:
        for parameter, average in zip(parameters, self._ema_parameters):
            parameter.data = average
        logits = self._forward_once(images)
        flipped_logits = self._forward_once(images.flip(-1))
        return 0.5 * (logits + flipped_logits)
    finally:
        for parameter, live_parameter in zip(parameters, live_parameters):
            parameter.data = live_parameter

